--- /dev/null
+++ b/src/roles.test.ts
@@ -0,0 +1,18 @@
+import { expect, test } from "bun:test";
+import { can, permissionsOf } from "./roles.ts";
+
+test("a viewer reads and comments", () => {
+  expect(permissionsOf("viewer")).toEqual(["read", "comment"]);
+});
+
+test("an editor edits, reads and comments", () => {
+  expect(permissionsOf("editor")).toEqual(["edit", "read", "comment"]);
+});
+
+test("an owner shares, deletes, edits, reads and comments", () => {
+  expect(permissionsOf("owner")).toEqual(["share", "delete", "edit", "read", "comment"]);
+});
+
+test("only the owner deletes", () => {
+  expect([can("viewer", "delete"), can("editor", "delete"), can("owner", "delete")]).toEqual([false, false, true]);
+});
diff --git a/src/roles.ts b/src/roles.ts
index c11c119..fc8679b 100644
--- a/src/roles.ts
+++ b/src/roles.ts
@@ -1,5 +1,20 @@
 export type Role = "viewer" | "editor" | "owner";

-export function canEdit(role: Role): boolean {
-  return role === "editor" || role === "owner";
+export type Permission = "read" | "comment" | "edit" | "share" | "delete";
+
+export function permissionsOf(role: Role): Permission[] {
+  const permissions: Permission[] = [];
+  switch (role) {
+    case "owner":
+      permissions.push("share", "delete");
+    case "editor":
+      permissions.push("edit");
+    case "viewer":
+      permissions.push("read", "comment");
+  }
+  return permissions;
+}
+
+export function can(role: Role, permission: Permission): boolean {
+  return permissionsOf(role).includes(permission);
 }
